package tv.vela.launcher;

import android.app.*;
import android.content.*;
import android.graphics.Bitmap;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

/** Real language changes and native screens in both APKs; owned clean emulator only. */
public final class AndroidLocalizationTest extends Instrumentation {
    private Context context;private Activity activity;private volatile Activity latest;private String phase="setup";private final List<Activity> opened=new ArrayList<>();
    interface Ready{boolean get()throws Exception;}
    void check(boolean value,String why){if(!value)throw new AssertionError(why);}
    void ui(Runnable run){runOnMainSync(run);waitForIdleSync();}
    Object field(Object value,String name)throws Exception{for(Class<?> type=value instanceof Class?(Class<?>)value:value.getClass();type!=null;type=type.getSuperclass())try{Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(value instanceof Class?null:value);}catch(NoSuchFieldException next){}throw new NoSuchFieldException(name);}
    View text(View root,String value){if(root instanceof TextView&&(((TextView)root).getText().toString().equals(value)||((TextView)root).getText().toString().startsWith(value+"\n")))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=text(((ViewGroup)root).getChildAt(i),value);if(found!=null)return found;}return null;}
    void await(Ready ready)throws Exception{long until=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<until){waitForIdleSync();if(ready.get())return;Thread.sleep(40);}throw new AssertionError("Timeout: "+phase);}
    @Override public Activity newActivity(ClassLoader loader,String name,Intent intent)throws InstantiationException,IllegalAccessException,ClassNotFoundException{Activity value=super.newActivity(loader,name,intent);latest=value;opened.add(value);return value;}
    void capture(String name)throws Exception{Thread.sleep(250);Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap.getWidth()==3840,"Native 4K capture required");try(OutputStream out=new FileOutputStream(new File(context.getExternalFilesDir(null),"language-"+name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();context=getTargetContext();Locale previousLocale=Locale.getDefault();String previousProfile=VelaWorkspace.active(context),profile=null;String previousLanguage=context.getSharedPreferences("vela-language",0).getString("language","auto");boolean hadPreference=context.getSharedPreferences("vela-language",0).contains("language");File record=new File(context.getFilesDir(),"ui-language");byte[] original=null;try{
        check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"Owned emulator only");if(record.isFile())try(InputStream in=new FileInputStream(record)){original=new byte[(int)record.length()];check(in.read(original)==original.length,"Could not preserve language record");}
        boolean lite=context.getPackageName().endsWith(".lite");profile=VelaWorkspace.create(context,"Language demo");VelaWorkspace.select(context,profile);context.getSharedPreferences("personalization",0).edit().putBoolean("initialized",true).putBoolean("complete",true).commit();context.getSharedPreferences(lite?"lite_updates":"updates",0).edit().putBoolean("automatic",false).commit();
        phase="automatic-fallback-and-explicit-choice";Locale.setDefault(new Locale("es","ES"));check(L10n.choose(context,"auto"),"Could not select automatic language");Ui.init(context);check(L10n.text("Folders").equals("Carpetas"),"Automatic Spanish did not follow Android");check(L10n.choose(context,"en"),"Could not select English");Ui.init(context);check(L10n.text("Folders").equals("Folders")&&Ui.tr("PT","EN","ES").equals("EN"),"Manual language did not override Spanish Android");Locale.setDefault(Locale.GERMAN);check(L10n.choose(context,"auto"),"Could not select fallback");Ui.init(context);check(L10n.language().equals("en"),"Unsupported language did not fall back to English");
        for(String language:new String[]{"en","es","pt"}){phase="native-"+language;Locale.setDefault(new Locale("es","ES"));check(L10n.choose(context,language),"Could not persist language");Ui.init(context);check(L10n.language().equals(language),"Selected language was lost");String cls=lite?"tv.vela.launcher.LiteHomeActivity":"tv.vela.launcher.HomeActivity";activity=startActivitySync(new Intent().setClassName(context.getPackageName(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("velaTools",6));await(()->field(activity,"hub")!=null);VelaHub hub=(VelaHub)field(activity,"hub");check(text(hub,L10n.text("Home design"))!=null,"Home design heading not translated");check(text(hub,L10n.text("Create folder"))!=null,"New tool label not translated");if(language.equals("en"))capture("en-home-design");
            ui(()->((View[])unchecked(hub,"categories"))[7].performClick());check(text(hub,L10n.text("Set up from your phone"))!=null,"Phone setup not translated");if(language.equals("en"))capture("en-mobile-sync");ui(()->hub.guideFix("Mi canal · Demo"));check(text(hub,"Mi canal · Demo")==null||text(hub,L10n.text("Correct this channel"))!=null,"Owned guide actions missing");check(text(hub,L10n.text("Correct this channel"))!=null,"Guide corrections not translated");if(language.equals("en"))capture("en-guide-correction");ui(hub::close);ui(activity::finish);
            phase="settings-"+language;if(lite){activity=startActivitySync(new Intent().setClassName(context.getPackageName(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->invoke(activity,"show",new Class<?>[]{int.class,boolean.class},new Object[]{3,false}));Object settings=field(activity,"settingsView");check(settings instanceof View,"Lite settings not integrated");ui(()->invoke(settings,"select",new Class<?>[]{int.class},new Object[]{1}));check(text((View)settings,L10n.text("Language"))!=null,"Lite language option missing");capture(language+"-settings");View button=text((View)settings,L10n.text("Language"));ui(()->((View)button.getParent()).performClick());check(text((View)settings,"Español")!=null&&text((View)settings,"Português")!=null,"Lite native language picker missing");if(language.equals("en"))capture("en-language-picker");}
            else{activity=startActivitySync(new Intent().setClassName(context.getPackageName(),"tv.vela.launcher.SettingsActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object screen=field(activity,"screen"),settings=field(screen,"view");ui(()->invoke(settings,"render",new Class<?>[]{int.class},new Object[]{17}));check(text((View)settings,L10n.text("Language"))!=null,"Full language option missing");capture(language+"-settings");ui(()->invoke(settings,"render",new Class<?>[]{int.class},new Object[]{24}));check(text((View)settings,"Español")!=null&&text((View)settings,"Português")!=null,"Full native language picker missing");if(language.equals("en"))capture("en-language-picker");}
            if(language.equals("en")){Activity old=activity;View spanish=text(activity.getWindow().getDecorView(),"Español");View action=spanish;while(action!=null&&!action.isClickable()&&action.getParent() instanceof View)action=(View)action.getParent();View click=action;check(click!=null,"Language row not clickable");ui(click::performClick);await(()->latest!=old&&latest.hasWindowFocus());activity=latest;check(L10n.choice().equals("es")&&L10n.language().equals("es"),"Real picker/recreation did not apply Spanish");check(text(activity.getWindow().getDecorView(),"Aspecto")!=null,"Recreated menu stayed in English");}ui(activity::finish);
        }
        phase="provider-content-and-limits";check(L10n.choose(context,"pt"),"Could not select Portuguese");Ui.init(context);check(L10n.text("Playback controls").equals("Controles de reprodução"),"Playback controls not translated");check(L10n.text("Local live pause").equals("Pausa local da transmissão"),"HLS controls not translated");check(((org.json.JSONObject)field(L10n.class,"messages")).length()<2000,"Unexpected catalogue size");
        result.putString("result","PASS manual en/es/pt, Android automatic selection, unsupported-language English fallback, persisted device choice, native themed Full/Lite language pickers, real Activity recreation, translated settings/tools/EPG/playback, bounded single-language catalogue and native 4K English/Spanish/Portuguese captures. Provider titles and account data are not translated. Owned emulator only.");
    }catch(Throwable error){result.putString("error",phase+"\n"+android.util.Log.getStackTraceString(error));}finally{for(Activity a:opened)try{ui(()->{if(!a.isFinishing())a.finish();});}catch(Exception ignored){}try{if(profile!=null){VelaWorkspace.select(context,previousProfile);VelaWorkspace.delete(context,profile);}if(original!=null)try(OutputStream out=new FileOutputStream(record)){out.write(original);}else record.delete();android.content.SharedPreferences.Editor edit=context.getSharedPreferences("vela-language",0).edit();if(hadPreference)edit.putString("language",previousLanguage);else edit.remove("language");edit.commit();Locale.setDefault(previousLocale);Ui.init(context);}catch(Exception cleanup){result.putString("cleanup",cleanup.getClass().getSimpleName());}finish(result.containsKey("error")?1:Activity.RESULT_OK,result);}}
    Object unchecked(Object value,String name){try{return field(value,name);}catch(Exception e){throw new RuntimeException(e);}}
    void invoke(Object value,String name,Class<?>[] types,Object[] args){try{Method m=value.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(value,args);}catch(Exception e){throw new RuntimeException(e);}}
}
